{
  "claims": [
    {
      "claim": "Valganciclovir oral bioavailability is reported as ~60% compared with ~6% for ganciclovir in humans. The query is unmodified ganciclovir, so this comparator directly indicates that its absolute oral bioavailability is far below the 20% threshold; a fasted state is unlikely to improve it to 20%.",
      "evidence_role": "supportive",
      "molecule_ids": [
        "Molecule 11"
      ],
      "record_ids": [
        "Record 11-4"
      ]
    },
    {
      "claim": "Prodrugs of ganciclovir reach pass-level bioavailability only after valyl/acyl ester modification: valganciclovir is 43–60% orally bioavailable in humans and a ganciclovir prodrug was ~40% bioavailable in rats. The query lacks these absorption-enhancing prodrug moieties, supporting low bioavailability for the unmodified parent.",
      "evidence_role": "supportive",
      "molecule_ids": [
        "Molecule 11",
        "Molecule 14"
      ],
      "record_ids": [
        "Record 11-1",
        "Record 11-4",
        "Record 11-7",
        "Record 14-1"
      ]
    },
    {
      "claim": "Several low-oral-bioavailability examples in humans are directionally consistent with fail, including a purine sulfonamide nucleoside with 4% absolute bioavailability, cefditoren with 14% fasted bioavailability, and selgantolimod with extremely poor oral bioavailability, although their structural similarity to the query is low.",
      "evidence_role": "supportive",
      "molecule_ids": [
        "Molecule 4",
        "Molecule 7",
        "Molecule 10"
      ],
      "record_ids": [
        "Record 4-1",
        "Record 7-1",
        "Record 10-1"
      ]
    },
    {
      "claim": "Some polar purine nucleoside analogs are orally bioavailable in humans, such as fludarabine (50–65%), cladribine (~40–46%), and a theophylline derivative (93%). These superficially support oral absorption, but they differ from the guanine/acyclic glycerol core of the query and are outweighed by the direct human ganciclovir comparator.",
      "evidence_role": "contradictory",
      "molecule_ids": [
        "Molecule 5",
        "Molecule 6",
        "Molecule 8"
      ],
      "record_ids": [
        "Record 5-1",
        "Record 6-1",
        "Record 6-5",
        "Record 8-1",
        "Record 8-2"
      ]
    },
    {
      "claim": "RP-170 shares the same glycerol acyclic side chain as the query and showed 73% oral bioavailability in dogs, superficially supporting absorption; however, it is dog data with a different heteroaromatic base and does not overcome the human ganciclovir evidence.",
      "evidence_role": "contradictory",
      "molecule_ids": [
        "Molecule 12"
      ],
      "record_ids": [
        "Record 12-1"
      ]
    },
    {
      "claim": "High oral bioavailability values for related prodrugs such as valomaciclovir stearate (>60%), AT-527 (at least 50%), and famciclovir/peniciclovir (~77%) depend on lipophilic or phosphate prodrug modifications absent from the query, limiting their transferability to unmodified ganciclovir.",
      "evidence_role": "contradictory",
      "molecule_ids": [
        "Molecule 1",
        "Molecule 3",
        "Molecule 15"
      ],
      "record_ids": [
        "Record 1-1",
        "Record 3-1",
        "Record 15-1"
      ]
    }
  ],
  "final_prediction": "fail"
}

